:root{
  --wine:#560916;
  --wine-dark:#2b070c;
  --wine-light:#7b1824;
  --gold:#9f6a1d;
  --gold-2:#c89335;
  --gold-light:#f1d28b;
  --ink:#35100e;
  --paper:#e8cc91;
  --paper-light:#f3dfb3;
  --red:#a91622;
  --orange:#c56b10;
  --green:#176328;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;min-height:100%;background:#120705;color:var(--ink);font-family:Georgia,'Times New Roman',serif}
body{min-height:100dvh;overflow:hidden}
button,input{font:inherit}
button{cursor:pointer}
.app-shell{position:relative;width:100%;max-width:480px;height:100dvh;margin:0 auto;overflow:hidden;background:#160806;box-shadow:0 0 55px #000}
.screen{position:absolute;inset:0;opacity:0;transform:translateX(8px);pointer-events:none;transition:opacity .24s ease,transform .24s ease;overflow-y:auto;overscroll-behavior:none;background:#160806}
.screen.active{opacity:1;transform:none;pointer-events:auto}
.page{position:relative;min-height:100%;overflow:hidden;padding:calc(18px + env(safe-area-inset-top)) 16px calc(26px + env(safe-area-inset-bottom));isolation:isolate}
.parchment-page{background:
  radial-gradient(circle at 17% 18%,rgba(115,68,18,.10) 0 1px,transparent 1.5px),
  radial-gradient(circle at 78% 31%,rgba(115,68,18,.08) 0 1px,transparent 1.5px),
  repeating-linear-gradient(100deg,rgba(90,44,10,.025) 0 1px,transparent 1px 6px),
  linear-gradient(112deg,rgba(255,255,255,.13),transparent 28%),
  radial-gradient(ellipse at center,#f3deb0 0%,#e8ca8e 66%,#d4aa62 100%)}
.parchment-page::before{content:"";position:absolute;inset:8px;border:2px solid #805315;border-radius:22px;box-shadow:inset 0 0 0 2px rgba(235,197,111,.7),inset 0 0 0 7px rgba(82,37,9,.11),inset 0 0 28px rgba(75,34,7,.22);pointer-events:none;z-index:5}
.parchment-page::after{content:"✦   ·   ✧   ·   ✦   ·   ✧   ·   ✦";position:absolute;left:12%;right:12%;top:16%;color:rgba(116,72,18,.38);font-size:13px;letter-spacing:14px;white-space:nowrap;transform:rotate(-12deg);pointer-events:none;z-index:-1}

/* selo LC */
.lc-seal{position:absolute;left:50%;top:calc(22px + env(safe-area-inset-top));transform:translateX(-50%);width:86px;height:86px;border-radius:50%;display:grid;place-items:center;z-index:8;color:var(--gold-light);font-size:38px;font-style:italic;background:radial-gradient(circle at 35% 28%,#741522,#360810 70%);border:3px solid var(--gold-2);box-shadow:0 0 0 2px #4d260d,0 6px 18px rgba(0,0,0,.35),inset 0 0 18px rgba(246,193,84,.18)}
.lc-seal::after{content:"";position:absolute;width:128px;height:44px;left:50%;top:53%;transform:translate(-50%,-50%);z-index:-1;background:linear-gradient(90deg,transparent,#8a5a17 18%,#c2943d 28%,transparent 30% 70%,#c2943d 72%,#8a5a17 82%,transparent);clip-path:polygon(0 46%,20% 22%,32% 45%,46% 0,50% 46%,54% 0,68% 45%,80% 22%,100% 46%,80% 74%,67% 52%,55% 100%,50% 54%,45% 100%,33% 52%,20% 74%)}
.inner-seal{width:72px;height:72px;font-size:31px;top:calc(16px + env(safe-area-inset-top))}

/* elementos celestes */
.celestial{position:absolute;color:#9a6418;text-shadow:0 1px rgba(255,255,255,.35);z-index:1;user-select:none}
.moon{left:34px;top:130px;font-size:62px;transform:rotate(-10deg)}
.star{font-size:24px}.star-a{right:38px;top:125px}.star-b{right:85px;top:190px}.star-c{left:44px;top:235px}
.inner-moon{right:26px;left:auto;top:116px;font-size:48px;opacity:.8}

/* topo / home */
.home-page{padding-top:calc(126px + env(safe-area-inset-top));padding-bottom:0;text-align:center}
.home-copy{position:relative;z-index:3;padding:2px 9px 320px}
.brand-intro{margin:0 0 14px;font-size:18px;line-height:1.05;letter-spacing:3px}.brand-intro span{font-size:13px;letter-spacing:2px}
.ornament-line{height:24px;display:flex;align-items:center;justify-content:center;color:#8a5716;margin:5px auto 3px;max-width:260px}
.ornament-line::before,.ornament-line::after{content:"";height:1px;flex:1;background:linear-gradient(90deg,transparent,#9b6d2a)}
.ornament-line::after{background:linear-gradient(90deg,#9b6d2a,transparent)}
.ornament-line span{margin:0 10px;font-size:20px}.ornament-line.small{max-width:210px}.ornament-line.compact{max-width:170px;height:18px;margin:3px auto 8px}.ornament-line.compact span{font-size:15px}
h1{margin:4px 0 8px;font-weight:500;color:#4a0a10;font-size:clamp(43px,12vw,60px);line-height:.98;letter-spacing:-1.2px}
.tagline{margin:0 0 25px;font-size:15px;letter-spacing:1.1px}

/* busca */
.search-box{width:100%;min-height:60px;border:1px solid rgba(116,74,28,.78);border-radius:17px;background:rgba(249,231,191,.76);display:flex;align-items:center;padding:0 16px;position:relative;box-shadow:inset 0 0 18px rgba(119,72,24,.08);z-index:4}
.search-icon{width:22px;height:22px;border:2px solid #471711;border-radius:50%;margin-right:14px;position:relative;flex:0 0 auto}
.search-icon::after{content:"";position:absolute;width:9px;height:2px;background:#471711;right:-6px;bottom:-3px;transform:rotate(45deg);border-radius:2px}
.search-box input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:#37100f;font-size:19px;padding:14px 0}.search-box input::placeholder{color:#7c674c}
.clear-btn{border:1px solid #92703e;background:transparent;color:#53301a;width:30px;height:30px;border-radius:50%;font-size:24px;line-height:24px;padding:0}

.magic-btn{width:100%;min-height:62px;margin-top:18px;border-radius:21px;border:2px solid #a87323;background:linear-gradient(#65101d,#450813 54%,#35050d);color:#f0d28a;font-size:20px;letter-spacing:.8px;box-shadow:0 0 0 2px #4a210c,0 7px 17px rgba(47,15,4,.24),inset 0 1px rgba(255,255,255,.12);position:relative;z-index:4;padding:12px 20px}
.magic-btn::before,.magic-btn::after{content:"✦";position:absolute;top:50%;transform:translateY(-50%);font-size:12px;color:#d0a047}.magic-btn::before{left:12px}.magic-btn::after{right:12px}
.magic-btn:active{transform:translateY(1px) scale(.997)}
.compact-label{font-size:16px;line-height:1.2}

/* arte inferior */
.mystic-table{position:absolute;left:9px;right:9px;bottom:8px;height:300px;background-image:linear-gradient(to bottom,rgba(232,204,145,0) 0%,rgba(232,204,145,.08) 7%,rgba(30,9,4,.02) 18%),url('data:image/png;base64,');background-size:cover;background-position:center bottom;border-radius:0 0 16px 16px;z-index:1;pointer-events:none}
.home-page .mystic-table{height:315px}

/* telas internas */
.inner-page{padding-top:calc(116px + env(safe-area-inset-top));min-height:100dvh}
.home-btn{position:absolute;left:22px;top:calc(24px + env(safe-area-inset-top));width:54px;height:54px;border-radius:50%;z-index:9;display:grid;place-items:center;border:2px solid #b27a26;background:linear-gradient(#65101d,#3a0710);box-shadow:0 0 0 2px #4d250e,0 5px 12px rgba(0,0,0,.2)}
.home-btn svg{width:28px;height:28px;fill:none;stroke:#efcc77;stroke-width:1.8;stroke-linejoin:round}
.screen-content{position:relative;z-index:3;text-align:center;padding:0 8px 270px}
.screen-title{font-size:clamp(28px,8vw,38px);font-weight:500;margin:22px 0 4px;color:#4b0b11}

/* resultados */
.results-content{padding-top:12px}
.results-search-box{margin-top:25px}
.results-list{display:flex;flex-direction:column;gap:10px;margin-top:17px}
.result-row{width:100%;min-height:65px;border:1px solid rgba(126,80,31,.38);border-radius:14px;background:rgba(250,231,190,.82);display:flex;align-items:center;justify-content:space-between;padding:12px 18px;color:#3c1411;font-size:18px;text-align:left;box-shadow:0 4px 12px rgba(88,45,12,.08)}
.result-row .chev{font-size:34px;line-height:1;color:#5b2316}.result-row:active{background:#f7ddb0}
.results-count{font-size:13px;letter-spacing:1px;margin:23px 0 0}
.empty-state{padding:32px 15px;font-size:17px;line-height:1.5;border:1px dashed rgba(126,80,31,.45);border-radius:14px;background:rgba(247,227,185,.58)}
.muted-table{opacity:.88;height:260px;filter:saturate(.9)}

/* prepare-se */
.test-page{padding-top:calc(112px + env(safe-area-inset-top))}
.test-content{padding-bottom:310px}
.eyebrow{margin:7px 0 3px;font-size:16px;letter-spacing:3px;color:#4b1712}
.person-name{margin:5px auto 12px;max-width:95%;font-size:clamp(38px,10vw,52px);font-weight:500;line-height:1.02;color:#490a10;overflow-wrap:anywhere}
.portal-art{width:min(92%,360px);aspect-ratio:560/470;margin:14px auto 14px;background:url('data:image/png;base64,') center/cover no-repeat;border-radius:8px;filter:drop-shadow(0 8px 10px rgba(67,33,10,.18))}
.test-copy{font-size:14px;line-height:1.4;letter-spacing:1.1px;margin:8px 0}
.test-actions{display:flex;flex-direction:column;gap:2px;margin-top:5px}.test-actions .magic-btn{margin-top:12px}
.test-table{height:270px;opacity:.97}

/* resultado */
.result-page{padding-top:calc(110px + env(safe-area-inset-top))}
.result-content{padding-bottom:310px}
.result-name{font-size:clamp(36px,9.8vw,50px);margin-bottom:12px}
.power-orb{--orb-glow:#d73b3f;width:min(78vw,320px);aspect-ratio:1;border-radius:50%;margin:15px auto 22px;display:grid;place-items:center;position:relative;border:5px solid #a77424;box-shadow:0 0 0 2px #4f2d11,0 0 0 10px rgba(194,140,53,.18),0 0 34px var(--orb-glow),inset 0 0 38px rgba(0,0,0,.28);overflow:hidden;transition:background .45s ease,box-shadow .45s ease}
.power-orb::before{content:"";position:absolute;inset:7%;border-radius:50%;border:1px solid rgba(250,218,145,.48);box-shadow:inset 0 0 28px rgba(255,255,255,.16)}
.power-orb::after{content:"";position:absolute;left:17%;top:9%;width:58%;height:24%;border-radius:50%;background:linear-gradient(rgba(255,255,255,.24),transparent);filter:blur(4px);transform:rotate(-12deg)}
.power-orb.low{--orb-glow:#d84b51;background:radial-gradient(circle at 40% 29%,#d35252 0%,#aa1721 42%,#650710 76%,#35040a 100%)}
.power-orb.mid{--orb-glow:#e49b35;background:radial-gradient(circle at 40% 29%,#e4a138 0%,#c5670e 42%,#7a2d05 76%,#3f1503 100%)}
.power-orb.high{--orb-glow:#4a9e5e;background:radial-gradient(circle at 40% 29%,#59a862 0%,#246c34 42%,#0e431e 76%,#06270f 100%)}
.power-orb #power-value{position:relative;z-index:4;color:#f5dc9e;font-size:clamp(72px,22vw,106px);line-height:1;text-shadow:0 3px 7px rgba(0,0,0,.35)}
.orb-star,.orb-moon{position:absolute;z-index:3;color:#f4cf72;text-shadow:0 0 9px rgba(251,198,76,.6)}.os1{top:17%;left:31%}.os2{top:18%;right:30%}.os3{bottom:18%;right:30%}.orb-moon{bottom:15%;left:45%;font-size:25px}
.quote-card{width:96%;margin:0 auto 12px;padding:18px 14px;border:1px solid #9e702c;background:rgba(242,218,173,.74);font-size:16px;line-height:1.5;box-shadow:inset 0 0 15px rgba(115,71,22,.07)}
.result-actions{display:flex;flex-direction:column;gap:2px}.result-actions .magic-btn{margin-top:12px}
.icon-label{display:flex;align-items:center;justify-content:center;gap:14px}.icon-label::before,.icon-label::after{display:none}
.mini-search{width:19px;height:19px;border:2px solid #f0d28a;border-radius:50%;position:relative}.mini-search::after{content:"";position:absolute;width:8px;height:2px;background:#f0d28a;right:-6px;bottom:-3px;transform:rotate(45deg)}
.result-table{height:270px;opacity:.95}

.reveal-pulse{animation:reveal .8s ease both}
@keyframes reveal{0%{transform:scale(.84);opacity:.15;filter:brightness(1.8)}70%{transform:scale(1.035)}100%{transform:scale(1);opacity:1;filter:none}}

@media(max-height:760px){
  .home-copy{padding-bottom:270px}.home-page .mystic-table{height:265px}
  .inner-page{padding-top:calc(102px + env(safe-area-inset-top))}.inner-seal{width:64px;height:64px;font-size:27px}
  .person-name{font-size:clamp(34px,9vw,46px)}.portal-art{width:min(78%,300px)}
  .power-orb{width:min(66vw,275px)}
}
@media(min-width:481px){body{display:grid;place-items:center}.app-shell{height:min(930px,100dvh);border-radius:34px;border:1px solid #6f4919}.screen{border-radius:34px}.parchment-page::before{border-radius:27px}}


/* ================= V5: ART-DIRECTED LAYOUT =================
   A decoração deixa de ser "rodapé" e vira parte dominante da composição.
*/
html,body{height:100%;overflow:hidden}
.app-shell,.screen,.page{height:100dvh;min-height:100dvh}
.screen{overflow:hidden}
.page{padding-bottom:0}

/* Pergaminho mais envelhecido e moldura mais marcada */
.parchment-page{
 background:
 radial-gradient(circle at 15% 10%,rgba(99,48,8,.14) 0 1px,transparent 1.7px),
 radial-gradient(circle at 84% 20%,rgba(99,48,8,.12) 0 1px,transparent 1.7px),
 radial-gradient(circle at 35% 67%,rgba(99,48,8,.08) 0 1px,transparent 1.7px),
 repeating-linear-gradient(93deg,rgba(80,38,5,.035) 0 1px,transparent 1px 4px),
 radial-gradient(ellipse at 50% 35%,#f6e5bd 0%,#e9ca8c 63%,#b87c2f 115%);
}
.parchment-page::before{
 inset:5px;border:3px solid #633607;border-radius:22px;
 box-shadow:inset 0 0 0 3px #d7a348,inset 0 0 0 7px rgba(73,30,3,.26),
 inset 0 0 42px rgba(64,26,3,.30),0 0 0 1px #1f0a02;
}
.parchment-page::after{
 content:"✦     ✧      ✦       ☾       ✦";
 left:8%;right:8%;top:16%;font-size:18px;letter-spacing:5px;
 color:rgba(112,64,12,.48);transform:none;text-align:center;
}

/* LC */
.lc-seal{width:78px;height:78px;top:calc(16px + env(safe-area-inset-top));font-size:35px}
.lc-seal::after{width:118px}
.inner-seal{width:66px;height:66px;font-size:29px;top:calc(13px + env(safe-area-inset-top))}

/* O cenário mágico ocupa a parte inferior de verdade */
.mystic-table,.home-page .mystic-table,.muted-table,.test-table,.result-table{
 display:block !important;
 position:absolute !important;
 left:5px !important;right:5px !important;bottom:5px !important;
 height:39% !important;min-height:285px !important;max-height:none !important;
 background-image:url('data:image/png;base64,') !important;
 background-size:auto 100% !important;
 background-repeat:no-repeat !important;
 background-position:center bottom !important;
 border-radius:0 0 18px 18px;
 opacity:1 !important;filter:none !important;
 z-index:2 !important;
}
.mystic-table::before{
 content:"";position:absolute;inset:-42px 0 auto;height:78px;
 background:linear-gradient(to bottom,rgba(232,202,143,0),rgba(232,202,143,.92) 58%,transparent);
}

/* TELA 1 */
.home-page{padding:calc(103px + env(safe-area-inset-top)) 24px 0;text-align:center}
.home-copy{padding:0;position:relative;z-index:4}
.brand-intro{font-size:16px;letter-spacing:3px;margin:0 0 5px}
.brand-intro span{font-size:11px}
.home-copy .ornament-line{height:14px;margin:0 auto}
h1{
 font-size:clamp(34px,9.4vw,44px)!important;
 line-height:1;letter-spacing:-.7px;white-space:nowrap;margin:4px 0 7px
}
.tagline{font-size:12px;letter-spacing:.8px;margin:0 0 10px}
.home-copy .ornament-line.small{height:11px;margin:0 auto 9px}
.search-box{min-height:54px;border-radius:15px;background:rgba(250,232,193,.92);box-shadow:0 3px 10px rgba(69,31,5,.14),inset 0 0 18px rgba(112,66,15,.10)}
.search-box input{font-size:17px}
.magic-btn{min-height:55px;margin-top:11px;border-radius:18px;font-size:18px}
.home-page .moon{top:123px;left:29px;font-size:46px}
.home-page .star-a{top:126px}.home-page .star-b{top:177px}.home-page .star-c{top:210px}

/* INTERNAS */
.inner-page{padding:calc(86px + env(safe-area-inset-top)) 22px 0}
.home-btn{left:17px;top:calc(16px + env(safe-area-inset-top));width:47px;height:47px}
.screen-content{padding:0 4px 300px;z-index:4}
.inner-moon{top:91px;right:25px;font-size:38px}
.screen-title{font-size:clamp(24px,6.7vw,31px);margin:12px 0 2px}
.results-content{padding-top:2px;padding-bottom:300px}
.results-search-box{margin-top:12px}
.results-list{margin-top:11px}
.result-row{min-height:58px;background:rgba(250,232,193,.94)}
.results-count{margin-top:14px}

/* PREPARE-SE */
.test-page{padding-top:calc(78px + env(safe-area-inset-top))}
.test-content{padding-bottom:290px}
.eyebrow{font-size:13px;margin:2px 0}
.person-name{font-size:clamp(29px,8vw,40px);line-height:.98;margin:2px auto 5px}
.portal-art{
 width:min(69%,270px);margin:4px auto 5px;aspect-ratio:560/470;
 filter:drop-shadow(0 7px 8px rgba(52,21,4,.30));
}
.test-copy{font-size:11px;line-height:1.3;margin:3px 0}
.ornament-line.compact{height:11px;margin:1px auto 4px}
.test-actions .magic-btn{margin-top:7px;min-height:50px}
.test-actions .compact-label{font-size:13px}

/* RESULTADO */
.result-page{padding-top:calc(76px + env(safe-area-inset-top))}
.result-content{padding-bottom:290px}
.result-name{font-size:clamp(28px,7.7vw,39px);margin:2px auto 5px}
.power-orb{width:min(49vw,218px);margin:5px auto 8px;border-width:4px}
.power-orb #power-value{font-size:clamp(58px,15vw,78px)}
.quote-card{width:92%;padding:8px 10px;font-size:12px;line-height:1.3;margin:0 auto 3px;background:rgba(244,220,176,.91)}
.result-actions .magic-btn{margin-top:7px;min-height:48px}
.result-actions .compact-label{font-size:12px}

/* A arte precisa aparecer mesmo em aparelhos menores */
@media(max-height:760px){
 .mystic-table,.home-page .mystic-table,.muted-table,.test-table,.result-table{
   height:34% !important;min-height:225px !important;
 }
 .home-page{padding-top:calc(91px + env(safe-area-inset-top))}
 .lc-seal{width:68px;height:68px;font-size:30px}
 h1{font-size:clamp(31px,8.8vw,40px)!important}
 .inner-page{padding-top:calc(70px + env(safe-area-inset-top))}
 .screen-content{padding-bottom:235px}
 .portal-art{width:min(58%,220px)}
 .power-orb{width:min(42vw,185px)}
}

/* ===== V6 SELF-CONTAINED ART ===== */
.mystic-table,
.home-page .mystic-table,
.muted-table,
.test-table,
.result-table {
  display:block !important;
  background-image:url('data:image/png;base64,') !important;
  background-repeat:no-repeat !important;
  background-position:center bottom !important;
  background-size:cover !important;
  opacity:1 !important;
  visibility:visible !important;
}
.portal-art {
  background-image:url('data:image/png;base64,') !important;
  background-repeat:no-repeat !important;
  background-position:center !important;
  background-size:cover !important;
}


/* tela intermediária · medindo poder */
.thinking-page{display:flex;align-items:center;justify-content:center;text-align:center}
.thinking-content{position:relative;z-index:4;width:100%;padding:105px 18px 260px}
.thinking-content .eyebrow{max-width:330px;margin:0 auto 8px;line-height:1.35}
.thinking-title{margin:18px 0 24px;color:var(--wine);font-size:clamp(27px,8vw,38px);font-weight:500;letter-spacing:1px}
.thinking-orb{width:180px;height:180px;margin:12px auto 26px;border-radius:50%;position:relative;display:grid;place-items:center;color:var(--gold-light);background:radial-gradient(circle at 38% 32%,#8a2634 0%,#5a0b18 42%,#2b070c 78%);border:3px solid var(--gold-2);box-shadow:0 0 0 3px rgba(77,38,13,.85),0 0 34px rgba(159,106,29,.55),inset 0 0 34px rgba(241,210,139,.18);animation:thinkingPulse 1.25s ease-in-out infinite}
.thinking-moon{font-size:72px;transform:rotate(-12deg);text-shadow:0 0 16px rgba(241,210,139,.5)}
.thinking-star{position:absolute;color:var(--gold-light);animation:thinkingTwinkle 1.05s ease-in-out infinite alternate}.ts1{top:24px;right:35px;font-size:23px}.ts2{bottom:31px;left:34px;font-size:18px;animation-delay:.3s}.ts3{top:71px;left:24px;font-size:15px;animation-delay:.6s}
.thinking-copy{margin:0;color:#5b2018;font-size:14px;letter-spacing:2px}
@keyframes thinkingPulse{0%,100%{transform:scale(.96);filter:brightness(.92)}50%{transform:scale(1.035);filter:brightness(1.15)}}
@keyframes thinkingTwinkle{from{opacity:.25;transform:scale(.7) rotate(0deg)}to{opacity:1;transform:scale(1.25) rotate(20deg)}}

/* V8 · moldura adaptada aos cantos arredondados do iPhone */
@supports (padding: max(0px)) {
  @media (max-width:480px) {
    .parchment-page::before{
      top:max(10px, calc(env(safe-area-inset-top) * .42));
      left:max(8px, calc(env(safe-area-inset-left) + 8px));
      right:max(8px, calc(env(safe-area-inset-right) + 8px));
      bottom:max(8px, calc(env(safe-area-inset-bottom) * .28));
      border-radius:clamp(24px, 7vw, 34px);
    }
  }
}


/* V9 · novo logo LC e mais respiro na tela de teste */
.lc-seal{
  font-size:0 !important;
  background:transparent url('./assets/lc-logo.png') center/contain no-repeat !important;
  border:0 !important;
  box-shadow:none !important;
  overflow:visible;
}
.lc-seal::after{display:none !important;}
.test-content .person-name{margin-bottom:30px;}
.test-content .portal-art{width:min(66%,250px);margin:0 auto 22px;}
@media (max-width:390px){
  .test-content .person-name{margin-bottom:26px;}
  .test-content .portal-art{width:min(60%,220px);}
}
